const fs = require('node:fs').promises
const limit = 1 << 20
const a = await fs.open('/data/f', 'r+')
const b = await fs.open('/data/f', 'r+')
try {
  await a.write(Buffer.alloc(limit, '.'))
  try {
    await a.sync()
  } catch (error) {
    if (error.code !== 'EDQUOT') throw error
    console.log('quota')
  }
  await fs.unlink('/data/reserved')
  await b.write('P', 0)
  await a.write('yz', limit)
  await a.sync()
  await b.sync()
} finally {
  await b.close()
  await a.close()
}
